INSERT INTO messages (id, school_id, sender_id, receiver_id, content, is_read, created_at) VALUES
  ('74000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000002', 'Rohan, please complete your trigonometry homework by tomorrow.', TRUE, '2026-04-01T10:00:00'),
  ('74000000-0000-0000-0000-000000000002', '11111111-1111-1111-1111-111111111111', '10000000-0000-0000-0000-000000000002', '20000000-0000-0000-0000-000000000002', 'Ma''am, I have completed the homework. Should I submit it online?', TRUE, '2026-04-01T10:15:00'),
  ('74000000-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', '20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000002', 'Yes, please upload it to the portal. Also, prepare for the quiz on Friday.', TRUE, '2026-04-01T10:30:00'),
  ('74000000-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', '20000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000003', 'Priya, can you share your physics notes from yesterday?', FALSE, '2026-04-02T14:00:00'),
  ('74000000-0000-0000-0000-000000000005', '11111111-1111-1111-1111-111111111111', '10000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000003', 'Sure Amit, I will share them with you after school.', FALSE, '2026-04-02T14:15:00'),
  ('74000000-0000-0000-0000-000000000006', '11111111-1111-1111-1111-111111111111', '20000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000004', 'Amit, your lab report is excellent. Keep up the good work!', TRUE, '2026-04-03T11:00:00'),
  ('74000000-0000-0000-0000-000000000007', '11111111-1111-1111-1111-111111111111', '10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000004', 'Thank you ma''am! I will work even harder.', TRUE, '2026-04-03T11:30:00'),
  ('74000000-0000-0000-0000-000000000008', '11111111-1111-1111-1111-111111111111', '20000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000005', 'Sneha, please submit your essay by Friday.', FALSE, '2026-04-04T09:00:00'),
  ('74000000-0000-0000-0000-000000000009', '11111111-1111-1111-1111-111111111111', '10000000-0000-0000-0000-000000000005', '20000000-0000-0000-0000-000000000005', 'Sir, I will submit it by tomorrow. Can I get an extension?', FALSE, '2026-04-04T09:30:00'),
  ('74000000-0000-0000-0000-000000000010', '11111111-1111-1111-1111-111111111111', '20000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000006', 'Vikram, your Python code has a bug. Let me help you debug it.', FALSE, '2026-04-05T16:00:00')
